class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False


def insert(root, word):
    node = root
    for ch in word:
        node = node.children.setdefault(ch, TrieNode())
    node.is_end = True


def count_matches(node, word, i):
    if i == len(word):
        return 1 if node.is_end else 0
    ch = word[i]
    if ch == ".":
        return sum(count_matches(child, word, i + 1) for child in node.children.values())
    child = node.children.get(ch)
    return count_matches(child, word, i + 1) if child else 0


root = TrieNode()
